package pe.com.asistencia.request.api;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import pe.com.asistencia.employee.repository.EmployeeRepository; import pe.com.asistencia.request.domain.Incident; import pe.com.asistencia.request.repository.IncidentRepository; import pe.com.asistencia.security.service.SupervisorScopeService; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/incidents") public class IncidentController {
 private final IncidentRepository incidents; private final EmployeeRepository employees; private final SupervisorScopeService scopes; public IncidentController(IncidentRepository i,EmployeeRepository e,SupervisorScopeService scopes){incidents=i;employees=e;this.scopes=scopes;}
 @GetMapping("/me") public List<View> mine(Authentication auth){var e=employees.findByUserUsernameIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Usuario sin empleado"));return incidents.findByEmployeeIdOrderByOccurredOnDesc(e.getId()).stream().map(View::of).toList();}
 @GetMapping @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')") public List<View> list(Authentication auth,@RequestParam(defaultValue="OPEN") String status){return incidents.findByStatusOrderByOccurredOnDesc(status.toUpperCase()).stream().filter(i->scopes.canAccess(auth,i.getEmployee().getId(),i.getOccurredOn())).map(View::of).toList();}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')") public View create(Authentication auth,@Valid @RequestBody CreateRequest r){if(!scopes.canAccess(auth,r.employeeId(),r.occurredOn()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"OUTSIDE_SUPERVISOR_SCOPE");var e=employees.findById(r.employeeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Empleado no encontrado"));return View.of(incidents.save(new Incident(e,r.type().toUpperCase(),r.description(),"MANUAL",r.occurredOn())));}
 @PatchMapping("/{id}/close") @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')") public View close(Authentication auth,@PathVariable Long id){var i=incidents.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Incidencia no encontrada"));if(!scopes.canAccess(auth,i.getEmployee().getId(),i.getOccurredOn()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"OUTSIDE_SUPERVISOR_SCOPE");i.close();return View.of(incidents.save(i));}
 public record CreateRequest(@NotNull Long employeeId,@NotBlank @Size(max=40) String type,@NotBlank @Size(max=500) String description,@NotNull LocalDate occurredOn){} public record View(Long id,Long employeeId,String type,String description,String status,String source,LocalDate occurredOn,Instant createdAt){static View of(Incident i){return new View(i.getId(),i.getEmployee().getId(),i.getType(),i.getDescription(),i.getStatus(),i.getSource(),i.getOccurredOn(),i.getCreatedAt());}}
}
